import * as React from 'react'
import { graphql, Link } from 'gatsby'
import { IGatsbyImageData, GatsbyImage, getImage } from 'gatsby-plugin-image'

import "../scss/main.scss"

import Header from "../components/Header"
import Footer from "../components/Footer"
import AccentDots from "../components/AccentDots"
import birdNames from "../data/bird-names.json"
import birdFacts from "../data/bird-facts.json"
import gridColours from "../data/grid-colours.json"

const MOVE_TARGETS: Record<number, number> = { 3: 15, 4: 25 }

interface PhotoNode {
  name: string
  relativeDirectory: string
  childImageSharp: {
    thumb: IGatsbyImageData
  }
}

interface PageProps {
  data: {
    photography: { nodes: PhotoNode[] }
  }
}

// Shuffle tiles, ensuring not already solved
const shuffleTiles = (size: number): number[] => {
  const total = size * size
  const tiles = Array.from({ length: total }, (_, i) => i)

  do {
    for (let i = tiles.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1))
      ;[tiles[i], tiles[j]] = [tiles[j], tiles[i]]
    }
  } while (tiles.every((t, i) => t === i))

  return tiles
}

// Background position for each tile value
const getTilePosition = (value: number, size: number): string => {
  const col = value % size
  const row = Math.floor(value / size)
  const step = 100 / (size - 1)
  return `${col * step}% ${row * step}%`
}

const BirdPuzzlePage: React.FC<PageProps> = ({ data }) => {
  const [gridSize, setGridSize] = React.useState(3)
  const [tiles, setTiles] = React.useState<number[]>(() => shuffleTiles(3))
  const [moves, setMoves] = React.useState(0)
  const [solved, setSolved] = React.useState(false)
  const [selectedIndex, setSelectedIndex] = React.useState<number | null>(null)
  const [dragIndex, setDragIndex] = React.useState<number | null>(null)
  const boardRef = React.useRef<HTMLDivElement>(null)
  const moveTarget = MOVE_TARGETS[gridSize]

  // Pick a random photo
  const photo = React.useMemo(() => {
    const images = data.photography.nodes
    return images[Math.floor(Math.random() * images.length)]
  }, [data.photography.nodes])

  const imageSrc = photo.childImageSharp.thumb.images?.fallback?.src || ''
  const thumbImage = getImage(photo.childImageSharp.thumb)

  const getBirdName = (): string => {
    const gallery = birdNames[photo.relativeDirectory as keyof typeof birdNames] || {}
    return gallery[photo.name as keyof typeof gallery] || ''
  }

  const birdName = getBirdName()

  const getBirdFact = (): string => {
    if (!birdName) return ''
    // Try exact match first
    if (birdFacts[birdName as keyof typeof birdFacts]) {
      return birdFacts[birdName as keyof typeof birdFacts]
    }
    // Try stripping trailing 's' for plurals
    const singular = birdName.replace(/s$/, '')
    if (birdFacts[singular as keyof typeof birdFacts]) {
      return birdFacts[singular as keyof typeof birdFacts]
    }
    // Try first species in combo names like "Redshank & Black-tailed Godwit"
    const first = birdName.split(' & ')[0].replace(/s$/, '')
    return birdFacts[first as keyof typeof birdFacts] || ''
  }

  const birdFact = getBirdFact()

  // Celebration dots — generated once when solved
  const celebrationDots = React.useMemo(() => {
    if (!solved) return []
    return Array.from({ length: 30 }, (_, i) => {
      const angle = (Math.random() * 360) * (Math.PI / 180)
      const distance = 80 + Math.random() * 160
      const x = Math.cos(angle) * distance
      const y = Math.sin(angle) * distance
      const size = 4 + Math.random() * 6
      const colour = gridColours[Math.floor(Math.random() * gridColours.length)]
      const delay = Math.random() * 0.3
      return { x, y, size, colour, delay, id: i }
    })
  }, [solved])

  // Check win after every move
  React.useEffect(() => {
    const isComplete = tiles.every((tile, index) => tile === index)
    if (isComplete && moves > 0) {
      setSolved(true)
    }
  }, [tiles, moves])

  const outOfMoves = moves >= moveTarget && !solved

  // Tap to select and swap
  const handleTileClick = (index: number) => {
    if (solved || outOfMoves) return

    if (selectedIndex === null) {
      // First tap — select this tile
      setSelectedIndex(index)
    } else if (selectedIndex === index) {
      // Tapped same tile — deselect
      setSelectedIndex(null)
    } else {
      // Second tap — swap tiles
      const newTiles = [...tiles]
      ;[newTiles[selectedIndex], newTiles[index]] = [newTiles[index], newTiles[selectedIndex]]
      setTiles(newTiles)
      setMoves(m => m + 1)
      setSelectedIndex(null)
    }
  }

  // Drag and drop — desktop
  const handleDragStart = (index: number) => {
    if (solved || outOfMoves) return
    setDragIndex(index)
    setSelectedIndex(null)
  }

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault()
  }

  const handleDrop = (targetIndex: number) => {
    if (dragIndex === null || dragIndex === targetIndex || solved || outOfMoves) return
    const newTiles = [...tiles]
    ;[newTiles[dragIndex], newTiles[targetIndex]] = [newTiles[targetIndex], newTiles[dragIndex]]
    setTiles(newTiles)
    setMoves(m => m + 1)
    setDragIndex(null)
  }

  // Touch drag — mobile
  const handleTouchStart = (index: number) => {
    if (solved || outOfMoves) return
    setDragIndex(index)
  }

  const handleTouchEnd = (e: React.TouchEvent) => {
    if (dragIndex === null || !boardRef.current) return

    const touch = e.changedTouches[0]
    const elements = document.elementsFromPoint(touch.clientX, touch.clientY)
    const targetTile = elements.find(el => el.hasAttribute('data-tile-index'))
    const targetIndex = targetTile ? parseInt(targetTile.getAttribute('data-tile-index') || '-1') : -1

    if (targetIndex >= 0 && targetIndex !== dragIndex) {
      const newTiles = [...tiles]
      ;[newTiles[dragIndex], newTiles[targetIndex]] = [newTiles[targetIndex], newTiles[dragIndex]]
      setTiles(newTiles)
      setMoves(m => m + 1)
    }

    setDragIndex(null)
  }

  // New puzzle
  const newPuzzle = () => {
    window.location.reload()
  }

  const resetPuzzle = () => {
    setTiles(shuffleTiles(gridSize))
    setMoves(0)
    setSolved(false)
    setSelectedIndex(null)
  }

  const switchDifficulty = (size: number) => {
    setGridSize(size)
    setTiles(shuffleTiles(size))
    setMoves(0)
    setSolved(false)
    setSelectedIndex(null)
  }

  return (
    <div className="container">
      <Header />

      <div className="bird-puzzle__hero">
        <Link to="/photography" className="back-link">&larr; Back to Photography</Link>
        <h1>Bird Shuffle</h1>
        <p>Shuffle the tiles, discover the bird</p>
        <AccentDots />
      </div>

      <div className="bird-puzzle__wrapper">
        <div className="bird-puzzle__content">
          {/* Reference image */}
          <div className="bird-puzzle__reference">
            {thumbImage && (
              <GatsbyImage
                image={thumbImage}
                alt="Complete image reference"
                className="bird-puzzle__reference-img"
              />
            )}
            <span className="bird-puzzle__reference-label">Reference</span>
          </div>

          {/* Puzzle board */}
          <div className="bird-puzzle__board-area">
          {solved && (
            <div className="bird-puzzle__celebration">
              {celebrationDots.map(dot => (
                <span
                  key={dot.id}
                  className="bird-puzzle__confetti-dot"
                  style={{
                    '--dot-x': `${dot.x}px`,
                    '--dot-y': `${dot.y}px`,
                    '--dot-size': `${dot.size}px`,
                    '--dot-colour': dot.colour,
                    '--dot-delay': `${dot.delay}s`,
                  } as React.CSSProperties}
                />
              ))}
            </div>
          )}
          <div
            className={`bird-puzzle__board bird-puzzle__board--${gridSize}x${gridSize}${solved ? ' is-solved' : ''}`}
            ref={boardRef}
          >
            {tiles.map((tileValue, index) => (
              <div
                key={index}
                data-tile-index={index}
                className={`bird-puzzle__tile${solved ? ' bird-puzzle__tile--solved' : ''}${selectedIndex === index ? ' bird-puzzle__tile--selected' : ''}${dragIndex === index ? ' bird-puzzle__tile--dragging' : ''}`}
                style={{
                  backgroundImage: `url(${imageSrc})`,
                  backgroundSize: `${gridSize * 100}% ${gridSize * 100}%`,
                  backgroundPosition: getTilePosition(tileValue, gridSize),
                }}
                onClick={() => handleTileClick(index)}
                draggable={!solved}
                onDragStart={() => handleDragStart(index)}
                onDragOver={handleDragOver}
                onDrop={() => handleDrop(index)}
                onTouchStart={() => handleTouchStart(index)}
                onTouchEnd={handleTouchEnd}
              />
            ))}
          </div>
          </div>

          {/* Difficulty toggle */}
          {/* {!solved && !outOfMoves && (
            <div className="bird-puzzle__difficulty">
              <button
                className={`bird-puzzle__diff-btn${gridSize === 3 ? ' is-active' : ''}`}
                onClick={() => switchDifficulty(3)}
              >3x3</button>
              <button
                className={`bird-puzzle__diff-btn${gridSize === 4 ? ' is-active' : ''}`}
                onClick={() => switchDifficulty(4)}
              >4x4</button>
            </div>
          )} */}

          {/* Controls */}
          <div className="bird-puzzle__controls">
            <div className="bird-puzzle__moves">
              {moves} {moves === 1 ? 'move' : 'moves'}
              {!solved && <span className="bird-puzzle__target"> · target: {moveTarget}</span>}
            </div>
            {solved ? (
              <div className="bird-puzzle__complete">
                {birdName && <div className="bird-puzzle__bird-name">{birdName}</div>}
                <div className="bird-puzzle__target-hit">Solved!</div>
                {birdFact && <p className="bird-puzzle__fact">{birdFact}</p>}
                <button className="bird-puzzle__button" onClick={newPuzzle}>
                  New Shuffle
                </button>
              </div>
            ) : outOfMoves ? (
              <div className="bird-puzzle__complete">
                <div className="bird-puzzle__out-of-moves">Out of moves!</div>
                <div className="bird-puzzle__actions">
                  <button className="bird-puzzle__button" onClick={resetPuzzle}>
                    Try Again
                  </button>
                  <button className="bird-puzzle__button" onClick={newPuzzle}>
                    New Photo
                  </button>
                </div>
              </div>
            ) : (
              <div className="bird-puzzle__actions">
                <button className="bird-puzzle__button" onClick={resetPuzzle}>
                  Reshuffle
                </button>
                <button className="bird-puzzle__button" onClick={newPuzzle}>
                  New Photo
                </button>
              </div>
            )}
          </div>
        </div>
      </div>

      <Footer />
    </div>
  )
}

export const pageQuery = graphql`
  query BirdPuzzleQuery {
    photography: allFile(
      filter: {
        sourceInstanceName: { eq: "photography" }
        relativeDirectory: { ne: "", nin: ["new-year-26"] }
      }
      sort: { name: ASC }
    ) {
      nodes {
        name
        relativeDirectory
        childImageSharp {
          thumb: gatsbyImageData(
            width: 600
            placeholder: BLURRED
          )
        }
      }
    }
  }
`

export default BirdPuzzlePage
